TLM.f("Sancti/12-29r",{"officium":"Die quinta post Nativitatem - S. Thomæ M.","rule":["vide ex Tempora/Nat30","Gloria","Credo","Prefatio=Nat"],"ruleInherited":["ex Sancti/12-25m3;","Gloria","Credo","Prefatio=Nat","Gloria","Credo","Prefatio=Nat","celebranda aut missa prima aut missa secunda aut missa tertia","no Ultima Evangelium"],"fallback":"Tempora/Nat30","from":{"Introitus":"Tempora/Nat30","Oratio":"Tempora/Nat30","Lectio":"Tempora/Nat30","Graduale":"Tempora/Nat30","Evangelium":"Tempora/Nat30","Offertorium":"Tempora/Nat30","Secreta":"Tempora/Nat30","Communio":"Tempora/Nat30","Postcommunio":"Tempora/Nat30"},"sections":{"Introitus":[{"k":"ref","la":"Isa 9:6"},{"k":"text","la":"Puer natus est nobis, et fílius datus est nobis: cujus impérium super húmerum ejus: et vocábitur nomen ejus magni consílii Angelus."},{"k":"ref","la":"Ps 97:1"},{"k":"text","la":"Cantáte Dómino cánticum novum, quia mirabília fecit."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Puer natus est nobis, et fílius datus est nobis: cujus impérium super húmerum ejus: et vocábitur nomen ejus magni consílii Angelus."}],"Oratio":[{"k":"text","la":"Concéde, quǽsumus, omnípotens Deus: ut nos Unigéniti tui nova per carnem Natívitas líberet; quos sub peccáti jugo vetústa sérvitus tenet."},{"k":"macro","name":"Per eundem"}],"Lectio":[{"k":"text","la":"Lectio Epístolæ beati Pauli Apostoli ad Titum."},{"k":"ref","la":"Tit 3:4-7"},{"k":"text","la":"Caríssime: Appáruit benígnitas et humánitas Salvatóris nostri Dei: non ex opéribus justítiæ, quæ fécimus nos, sed secúndum suam misericórdiam salvos nos fecit per lavácrum regeneratiónis et renovatiónis Spíritus Sancti, quem effúdit in nos abúnde per Jesum Christum, Salvatorem nostrum: ut, justificáti grátia ipsíus, herédes simus secúndum spem vitæ ætérnæ: in Christo Jesu, Dómino nostro."}],"Graduale":[{"k":"ref","la":"Ps 97: 3, 4, 2"},{"k":"text","la":"Vidérunt omnes fines terræ salutare Dei nostri: jubiláte Deo, omnis terra."},{"k":"text","la":"Notum fecit Dominus salutare suum: ante conspéctum géntium revelávit justitiam suam. Allelúja, allelúja.","mark":"V"},{"k":"text","la":"Dies sanctificátus illúxit nobis: veníte, gentes, et adoráte Dóminum: quia hódie descéndit lux magna super terram. Allelúja.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam."},{"k":"ref","la":"Luc 2:15-20"},{"k":"text","la":"In illo témpore: Pastóres loquebántur ad ínvicem: Transeámus usque Béthlehem, et videámus hoc verbum, quod factum est, quod Dóminus osténdit nobis. Et venérunt festinántes: et invenérunt Maríam, et Joseph, et Infántem pósitum in præsépio. Vidéntes autem cognovérunt de verbo, quod dictum erat illis de Púero hoc. Et omnes, qui audiérunt, miráti sunt: et de his, quæ dicta erant a pastóribus ad ipsos. María autem conservábat ómnia verba hæc, cónferens in corde suo. Et revérsi sunt pastóres, glorificántes et laudántes Deum in ómnibus, quæ audíerant et víderant, sicut dictum est ad illos."}],"Offertorium":[{"k":"ref","la":"Ps 88:12; 88:15"},{"k":"text","la":"Tui sunt cœli et tua est terra: orbem terrárum et plenitúdinem ejus tu fundásti: justítia et judícium præparátio sedis tuæ."}],"Secreta":[{"k":"text","la":"Obláta, Dómine, múnera, nova Unigéniti tui Nativitáte sanctífica: nosque a peccatórum nostrórum máculis emúnda."},{"k":"macro","name":"Per eundem"}],"Communio":[{"k":"ref","la":"Ps 97:3"},{"k":"text","la":"Vidérunt omnes fines terræ salutáre Dei nostri."}],"Postcommunio":[{"k":"text","la":"Præsta, quǽsumus, omnípotens Deus: ut natus hódie Salvátor mundi, sicut divínæ nobis generatiónis est auctor; ita et immortalitátis sit ipse largítor:"},{"k":"macro","name":"Qui tecum"}],"Commemoratio Oratio":[{"k":"rubric","la":"Pro S. Thoma Martyre"},{"k":"text","la":"Deus, pro cujus Ecclésia gloriósus Póntifex Thomas gládiis impiórum occúbuit: præsta, quǽsumus; ut omnes, qui ejus implórant auxílium, petitiónis suæ salutárem consequántur efféctum."},{"k":"macro","name":"Per Dominum"}],"Commemoratio Secreta":[{"k":"text","la":"Múnera tibi, Dómine, dicáta sanctífica: et, intercedénte beáto Thoma Mártyre tuo atque Pontífice, per éadem nos placátus inténde."},{"k":"macro","name":"Per Dominum"}],"Commemoratio Postcommunio":[{"k":"rubric","la":"Pro S. Thoma Martyre"},{"k":"text","la":"Hæc nos commúnio, Dómine, purget a crímine: et, intercedénte beáto Thoma Mártyre tuo atque Pontífice, coeléstis remédii fáciat esse consórtes."},{"k":"macro","name":"Per Dominum"}]},"hr":{"2556a7cf67c03224":{"t":"Iz 9, 6, Ps 97, 1\n(Iz 9, 6) Dijete nam se rodilo i Sin nam je darovan. Znak mu je vlasti na ramenu, a ime mu je Anđeo velikoga savjeta. (Ps 97, 1) Pjevajte Gospodinu novu pjesmu, jer učini divna djela.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Iz 9, 6) Dijete nam se rodilo i Sin nam je darovan. Znak mu je vlasti na ramenu, a ime mu je Anđeo velikoga savjeta.","v":"∅ → filius; ∅ → filius"},"77f61766a40a00f2":{"t":"<i>Pomolimo se</i>.\nPodaj, molimo, svemogući Bože, da novo tjelesno rođenje tvoga jedinorođenog Sina oslobodi nas, koje staro sužanjstvo tišti jarmom grijeha.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"e0f30f9a6fa2333c":{"t":"Tit 3, 4-7\nČitanje Poslanice bl. Pavla apostola Titu. Predragi: objavila se dobrota i čovjekoljublje Boga našega Spasitelja. On nas je spasio, ali ne po našim pravednim djelima nego po svojem milosrđu, po kupelji preporoda i obnove Duha Svetoga. Njega je na nas obilno izlio po našem Spasitelju Isusu Kristu, da opravdani njegovom milošću budemo po ufanju baštinici vječnog života u našem Gospodinu Isusu Kristu."},"450255e358a9cd68":{"t":"Ps 97, 3-4 i 2\nSvi krajevi zemlje vidješe spasenje Boga našega. Kličite Bogu, sve zemlje. Gospodin je objavio svoje spasenje, otkrio svoju pravdu pred licem naroda.\n\n<i>Aleluja</i>, <i>aleluja</i>.\nZasjao nam je posvećeni dan. Dođite, narodi, i poklonite se Gospodinu, jer je danas velika svjetlost sašla na zemlju. <i>Aleluja</i>."},"87d338e1955655ec":{"t":"Lk 2, 15-20\nSlijedi sveto Evanđelje po Luki. U ono vrijeme: pozovu pastiri jedan drugoga: »Pođimo u Betlehem da vidimo što se dogodilo, kako nam je objavio Gospodin!« Pođu žurno i nađu Mariju i Josipa i Dijete položeno u jasle. Kad su vidjeli, shvatili su što im je rečeno o tom Djetetu. Svi koji su čuli, divili su se onome što su im kazivali pastiri. Sve je te riječi Marija pamtila razmišljajući u svom srcu. A pastiri se vrate slaveći Boga za sve što su čuli i vidjeli, kako im je bilo rečeno."},"1dcee0ba49089f56":{"t":"Ps 88, 12 i 15\nTvoja su nebesa, tvoja je zemlja, ti si stvorio zemaljski krug i sve što je na njemu. Pravda i pravo temelji su prijestolja tvoga."},"748a928b3dfd448c":{"t":"Prinesene darove, Gospodine, posveti novim rođenjem svoga Jedinorođenca, a nas od ljaga naših grijeha očisti.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"46276ff06c5f858a":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine sveti Oče, svemogući i vječni Bože: jer je po tajni utjelovljene Riječi očima naše duše sinula nova svjetlost tvoga sjaja. Te dok tjelesnim očima spoznajemo Boga, on nas zanosi ljubavlju prema nevidljivim dobrima. I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:"},"3497b8df953b1338":{"t":"Ps 97, 3\nSvi krajevi zemlje vidješe spasenje Boga našega."},"6e3f222713b3fa12":{"t":"<i>Pomolimo se</i>.\nPodaj, molimo, svemogući Bože, kao što je danas rođeni Spasitelj svijeta začetnik našega božanskoga rođenja, tako da bude i darovatelj besmrtnosti.\n<i>Koji s Tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
